    back_text: 'Remodeling Phase\nTiming: 21 days to 2 years\n\nKey Processes:\n- Type III collagen replaced by Type I collagen\n- Collagen fibers reorganize along stress lines\n- Scar tissue strengthens\n- Vascularity decreases (scar becomes paler)\n\nMaximum Strength: 80% of original tissue\n- Achieved at approximately 1 year\n- Never reaches 100%\n\nFactors affecting remodeling:\n- Mechanical stress (helps alignment)\n- Nutrition\n- Age (slower in elderly)',
