    front_text: 'What is the Ober Test?',
    back_text: 'Ober Test:\n\nPurpose: Tests for tight TFL or ITB\n\nProcedure:\n• Patient sidelying, bottom leg flexed\n• Examiner abducts and extends top leg\n• Slowly lower leg toward table\n\nPositive Test:\n• Leg remains ABDUCTED (doesn\'t drop to table)\n• Indicates tight TFL or ITB\n\nModified Ober:\n• Knee extended (more specific for ITB)\n\nCommon in: ITB syndrome, runners',
    source_pdf_id: null,
