    front_text: 'What are the Lachman and Anterior Drawer tests?',
    back_text: 'ACL Integrity Tests:\n\nLACHMAN TEST (most sensitive):\n• Knee at 20-30° flexion\n• Stabilize femur, translate tibia anteriorly\n• Positive: Excessive anterior translation, soft end-feel\n\nANTERIOR DRAWER:\n• Knee at 90° flexion\n• Sit on patient\'s foot\n• Pull tibia forward\n• Positive: >6mm anterior translation\n\nLachman preferred - hamstrings relaxed, less meniscal blocking',
