    front_text: 'What do Valgus and Varus Stress Tests assess?',
    back_text: 'Collateral Ligament Tests:\n\nVALGUS STRESS TEST (MCL):\n• Apply lateral force to knee\n• Tests MEDIAL collateral ligament\n• At 0°: Tests MCL + posterior capsule\n• At 30°: Isolates MCL\n\nVARUS STRESS TEST (LCL):\n• Apply medial force to knee\n• Tests LATERAL collateral ligament\n• At 0°: Tests LCL + posterior capsule\n• At 30°: Isolates LCL\n\nGrading: I (<5mm), II (5-10mm), III (>10mm)',
    source_pdf_id: null,
