    back_text: 'Gait Cycle Definitions:\n\nGAIT CYCLE:\n• Time between two consecutive heel strikes of SAME foot\n• Synonymous with STRIDE length\n• One stride = two steps\n\nMeasurements:\n• Stride length: ~56 in (142 cm)\n• Step length: ~28 in (71 cm)\n• Step width: 2-4 in (5-10 cm) - forms BOS\n• Cadence: 90-120 steps/min\n• Gait speed: 1.4 m/s (3 mph)\n\nMnemonic: strIde = Ipsilateral leg',
