    back_text: 'Center of Gravity & Pelvic Motion:\n\nCOG Location:\n• ~2 inches anterior to S2\n• Slightly higher in males\n• Propulsion pushes COG anterior to BOS\n\nLATERAL PELVIC SHIFT:\n• Normal: 1-2 in (2.5-5 cm)\n• Centers weight over stance leg\n• Increases with wider BOS\n• Weak abductors → Trendelenburg gait\n\nVERTICAL PELVIC SHIFT:\n• Normal: <2 in (5 cm)\n• High point: Midstance\n• Low point: Initial contact',
